import {useState} from 'react'
import {TrafficDataTable} from '../TrafficDataTable'
import {Link, Truncate, Button} from '@primer/react'
import {clsx} from 'clsx'
import styles from '../Traffic.module.css'
import type {TrafficDataItem} from '../../hooks/traffic-types'

interface Props {
  referringSites: TrafficDataItem[] | undefined
  referringPaths: TrafficDataItem[] | undefined
  isLoading: boolean
  error: string | undefined
}

export function SitesTrafficTable({referringSites, referringPaths, isLoading, error}: Props) {
  const [selectedReferrer, setSelectedReferrer] = useState<string>()

  // when a referrer is selected, filter the paths for that referrer
  const displayData = selectedReferrer ? referringPaths?.filter(i => i.site === selectedReferrer) : referringSites

  return (
    <SitesTrafficInternalTable
      data={displayData}
      isLoading={isLoading}
      error={error}
      selectedReferrer={selectedReferrer}
      onReferrerSelected={setSelectedReferrer}
    />
  )
}

interface SitesTrafficInternalTableProps {
  data: TrafficDataItem[] | undefined
  isLoading: boolean
  error: string | undefined
  selectedReferrer: string | undefined
  onReferrerSelected: (referrer: string | undefined) => void
}
function SitesTrafficInternalTable({
  data,
  isLoading,
  error,
  selectedReferrer,
  onReferrerSelected,
}: SitesTrafficInternalTableProps) {
  const hasData = Array.isArray(data) && data.length > 0 && data.some(item => item.views > 0 || item.uniqueVisitors > 0)

  // Create the title with clickable "Domains" link if we're showing referring paths
  const getTitle = () => {
    if (selectedReferrer) {
      return (
        <>
          <Button variant="link" onClick={() => onReferrerSelected(undefined)}>
            Domains
          </Button>
          <span> / Referring pages</span>
        </>
      )
    }
    return 'Referring sites'
  }

  const renderSiteCell = (item: TrafficDataItem) => {
    return <TableCell item={item} selectedReferrer={selectedReferrer} onReferrerSelected={onReferrerSelected} />
  }

  return (
    <div className={clsx(styles.bottomSectionColumn, 'tmp-pb-6')}>
      <TrafficDataTable
        title={getTitle()}
        data={hasData ? data : []}
        isLoading={isLoading}
        error={error}
        columns={[
          {
            header: 'Site',
            field: 'site',
            rowHeader: true,
            renderCell: renderSiteCell,
          },
          {
            header: 'Views',
            field: 'views',
          },
          {
            header: 'Unique Visitors',
            field: 'uniqueVisitors',
          },
        ]}
        emptyMessage="No referring sites data available for this period"
        ariaLabelledBy="referring-sites"
      />
    </div>
  )
}

interface TableCellProps {
  item: TrafficDataItem
  selectedReferrer: string | undefined
  onReferrerSelected: (referrer: string | undefined) => void
}

function TableCell({item, selectedReferrer, onReferrerSelected}: TableCellProps) {
  const siteValue = item.site

  if (selectedReferrer) {
    const pathValue = item.path
    if (pathValue && pathValue !== 'Unknown' && !pathValue.includes('unknown-')) {
      // for referrers, the path value is the entire URL, so get only the path using the URL constructor.
      // do not pass in a base because this will never be relative.
      // eslint-disable-next-line no-restricted-syntax
      const url = new URL(pathValue)
      const pathOnly = url.pathname + url.search + url.hash

      return (
        <Link href={pathValue} target="_blank" rel="noopener noreferrer">
          <Truncate title={pathOnly} maxWidth="200px" inline>
            {pathOnly}
          </Truncate>
        </Link>
      )
    }

    return pathValue || 'Unknown'
  } else {
    const display = siteValue || 'Unknown'

    if (item.referrerPathsAllowed) {
      return (
        <Button variant="link" onClick={() => onReferrerSelected(display)}>
          <Truncate title={display} inline maxWidth="200px">
            {display}
          </Truncate>
        </Button>
      )
    }

    return (
      <Truncate title={display} inline maxWidth="200px">
        {display}
      </Truncate>
    )
  }
}
