import {useQuery} from '@github-ui/react-query'
import {useRepoContext} from './use-repo-context'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {
  RawPopularContentItem,
  RawReferringPathItem,
  RawReferringSiteItem,
  RawTrafficDataPoint,
  TrafficData,
  TrafficDataPoint,
  TrafficSummary,
} from './traffic-types'
import {
  transformPopularContent,
  transformReferringPaths,
  transformReferringSites,
  transformTrafficData,
} from '../utils/transform-traffic-data'

interface TrafficPayload {
  summary: TrafficSummary
  counts: RawTrafficDataPoint[]
}

interface DataPayload {
  views: TrafficPayload
  clones: TrafficPayload
  top_referrers: RawReferringSiteItem[]
  top_content: RawPopularContentItem[]
  top_referrer_paths: RawReferringPathItem[]
}

interface ErrorPayload {
  error: string
}

const GENERIC_ERROR_MESSAGE = 'Failed to fetch traffic data'

export function useCompleteTrafficData() {
  const {owner, repo} = useRepoContext()

  const path = `/${owner}/${repo}/graphs/traffic-data`

  return useQuery({
    queryKey: ['complete-traffic-data', path],
    refetchOnWindowFocus: false,
    queryFn: async () => {
      const response = await verifiedFetchJSON(path)
      if (!response.ok) {
        throw new Error(GENERIC_ERROR_MESSAGE)
      }

      let data: DataPayload | ErrorPayload
      try {
        data = await response.json()
      } catch {
        throw new Error(GENERIC_ERROR_MESSAGE)
      }

      if ('error' in data) {
        throw new Error(data.error)
      }

      return data
    },
    select: data => {
      return {
        clones: transformTrafficData(toTrafficData(data.clones), {includeUnique: false}),
        cloners: transformTrafficData(toTrafficData(data.clones), {includeTotal: false}),
        views: transformTrafficData(toTrafficData(data.views), {includeUnique: false}),
        visitors: transformTrafficData(toTrafficData(data.views), {includeTotal: false}),
        referringSites: transformReferringSites(data.top_referrers),
        popularContent: transformPopularContent(data.top_content),
        referringPaths: transformReferringPaths(data.top_referrer_paths),
      }
    },
  })
}

function toTrafficData(data: TrafficPayload): TrafficData {
  return {
    summary: data.summary,
    counts: data.counts.map(toTrafficPoint),
  }
}

function toTrafficPoint(count: RawTrafficDataPoint): TrafficDataPoint {
  return {
    bucket: count.bucket,
    date: new Date(count.bucket * 1000),
    total: count.total,
    unique: count.unique,
  }
}
