import {Heading} from '@primer/react'
import {RealTrafficGraph} from '../components/RealTrafficGraph'
import {TrafficError} from '../components/TrafficError'
import {useCompleteTrafficData} from '../hooks/use-complete-traffic-data'
import {SitesTrafficTable} from '../components/tables/SitesTrafficTable'
import {ContentTrafficTable} from '../components/tables/ContentTrafficTable'

export function Traffic() {
  const {data, isLoading, error} = useCompleteTrafficData()
  const errorMessage = error?.message

  const commonChartProps = {
    loading: isLoading,
    error: errorMessage ?? undefined,
  }

  return (
    <div className="width-full">
      {errorMessage && <TrafficError error={errorMessage} />}

      <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default tmp-mt-3">
        Git clones
      </Heading>
      <div className="d-flex flex-wrap gap-4 mt-2">
        <RealTrafficGraph
          data={data?.clones}
          {...commonChartProps}
          title="Clones in last 14 days"
          yAxisTitle="Clones"
        />
        <RealTrafficGraph
          data={data?.cloners}
          {...commonChartProps}
          title="Unique cloners in last 14 days"
          yAxisTitle="Cloners"
        />
      </div>

      <Heading as="h2" className="f3 text-semibold mb-1 color-fg-default tmp-mt-4">
        Visitors
      </Heading>
      <div className="d-flex flex-wrap gap-4 mt-2">
        <RealTrafficGraph
          data={data?.views}
          {...commonChartProps}
          title="Total views in last 14 days"
          yAxisTitle="Total views"
        />
        <RealTrafficGraph
          data={data?.visitors}
          {...commonChartProps}
          title="Unique visitors in last 14 days"
          yAxisTitle="Unique visitors"
        />
      </div>

      <div className="d-flex flex-wrap gap-4 tmp-mt-4">
        <SitesTrafficTable
          referringSites={data?.referringSites}
          referringPaths={data?.referringPaths}
          isLoading={isLoading}
          error={errorMessage}
        />
        <ContentTrafficTable data={data?.popularContent} isLoading={isLoading} error={errorMessage} />
      </div>
    </div>
  )
}
