import type {
  RawPopularContentItem,
  RawReferringPathItem,
  RawReferringSiteItem,
  TrafficData,
  TrafficDataItem,
} from '../hooks/traffic-types'

interface ChartDataPoint {
  name: string
  data: number[]
}

export interface TrafficChartData {
  chartData: ChartDataPoint[]
  categories: string[]
  maxValue: number // Maximum value for y-axis
  summary: {
    total: number
    unique: number
  }
  dateRangeHeader?: string // Added for displaying the date range in the header
}

/**
 * Creates a formatted date range header in the format "Month Day, Year — Month Day, Year"
 */
function createDateRangeHeader(data: TrafficData): string {
  if (!data || !data.counts || data.counts.length === 0) {
    return ''
  }

  const sortedDates = [...data.counts].map(count => count.date).sort((a, b) => a.getTime() - b.getTime())

  // We know these dates exist since we checked data.counts.length > 0
  const firstDate = sortedDates[0]
  const lastDate = sortedDates[sortedDates.length - 1]

  const formatDate = (date: Date | undefined): string => {
    if (!date) return ''
    return date.toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    })
  }

  return `${formatDate(firstDate)} — ${formatDate(lastDate)}`
}

/**
 * Transforms backend traffic data into format expected by TrafficGraph component
 */
export function transformTrafficData(
  data: TrafficData,
  options: {
    includeTotal?: boolean
    includeUnique?: boolean
  } = {},
): TrafficChartData {
  const {includeTotal = true, includeUnique = true} = options // Default options
  // Handle empty or invalid data
  if (!data || !data.counts || data.counts.length === 0) {
    return {
      chartData: [],
      categories: [],
      maxValue: 0,
      summary: {total: 0, unique: 0},
    }
  }

  // Sort counts by date to ensure proper order
  const sortedCounts = [...data.counts].sort((a, b) => a.date.getTime() - b.date.getTime())

  const categories = sortedCounts.map(count => {
    // Format as MM/DD - directly extract month and day
    const month = String(count.date.getUTCMonth() + 1).padStart(2, '0')
    const day = String(count.date.getUTCDate()).padStart(2, '0')
    return `${month}/${day}`
  })

  // Build chart data series
  const chartData: ChartDataPoint[] = []

  if (includeTotal) {
    chartData.push({
      name: 'Total',
      data: sortedCounts.map(count => count.total),
    })
  }

  if (includeUnique) {
    chartData.push({
      name: 'Unique',
      data: sortedCounts.map(count => count.unique),
    })
  }

  // Calculate max value for y-axis
  const allValues = chartData.flatMap(series => series.data)
  const maxValue = Math.max(...allValues, 0)

  return {
    chartData,
    categories,
    maxValue,
    summary: data.summary,
    dateRangeHeader: createDateRangeHeader(data),
  }
}

export function transformReferringSites(rawData: RawReferringSiteItem[]): TrafficDataItem[] {
  return rawData.map((item, index) => ({
    id: item.referrer || `unknown-${index}`,
    site: item.referrer || 'Unknown',
    views: item.count || 0,
    uniqueVisitors: item.uniques || 0,
    referrerPathsAllowed: item.referrer_paths_allowed,
  }))
}

export function transformPopularContent(rawData: RawPopularContentItem[]): TrafficDataItem[] {
  return rawData.map((item, index) => ({
    id: item.path || `unknown-${index}`,
    site: item.title || item.path || 'Unknown', // Use title for display, fallback to path then Unknown
    path: item.path, // Keep the original path for linking
    title: item.title, // Keep the original title
    views: item.count || 0,
    uniqueVisitors: item.uniques || 0,
  }))
}

export function transformReferringPaths(rawData: RawReferringPathItem[]): TrafficDataItem[] {
  return rawData.map((item, index) => ({
    id: item.full_url || `unknown-${index}`,
    site: item.referrer,
    path: item.full_url,
    views: item.count || 0,
    uniqueVisitors: item.uniques || 0,
  }))
}
