import {TrafficDataTable} from '../TrafficDataTable'
import {Link, Truncate} from '@primer/react'
import {clsx} from 'clsx'
import styles from '../Traffic.module.css'
import type {TrafficDataItem} from '../../hooks/traffic-types'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'

interface Props {
  data: TrafficDataItem[] | undefined
  isLoading: boolean
  error: string | undefined
}

export function ContentTrafficTable({data, isLoading, error}: Props) {
  const hasData = Array.isArray(data) && data.length > 0 && data.some(item => item.views > 0 || item.uniqueVisitors > 0)

  return (
    <div
      className={clsx(styles.bottomSectionColumn, 'tmp-pb-6')}
      data-issue-and-pr-hovercards-enabled
      data-commit-hovercards-enabled
      data-discussion-hovercards-enabled
    >
      <TrafficDataTable
        title="Popular content"
        data={hasData ? data : []}
        isLoading={isLoading}
        error={error}
        columns={[
          {
            header: 'Content',
            field: 'site',
            rowHeader: true,
            renderCell: item => <TableCell item={item} />,
          },
          {
            header: 'Views',
            field: 'views',
          },
          {
            header: 'Unique Visitors',
            field: 'uniqueVisitors',
          },
        ]}
        emptyMessage="No popular content data available for this period"
        ariaLabelledBy="popular-content"
      />
    </div>
  )
}

/**
 * Parse a path like `/<owner>/<repo>/issues/123` into hovercard attributes
 * for supported link types (issues, pull requests, commits, discussions).
 */
function getHovercardAttrsForPath(
  linkPath: string,
  getHovercardAttributesForType: ReturnType<typeof useGetHovercardAttributesForType>,
) {
  // Paths are /<owner>/<repo>/...  with no trailing slash or query params
  const segments = linkPath.split('/').filter(Boolean)
  if (segments.length < 3) return {}

  const [owner, repo, type, value] = segments
  if (!value) {
    return {}
  }

  const number = parseInt(value, 10)
  const isNumber = !Number.isNaN(number)

  if (type === 'issues' && isNumber) {
    return getHovercardAttributesForType('issue', {owner, repo, issueNumber: number, tracking: false})
  } else if (type === 'pull' && isNumber) {
    return getHovercardAttributesForType('pull_request', {owner, repo, pullRequestNumber: number, tracking: false})
  } else if (type === 'commit') {
    return getHovercardAttributesForType('commit', {owner, repo, commitish: value, tracking: false})
  } else if (type === 'discussions' && isNumber) {
    return getHovercardAttributesForType('discussion', {owner, repo, discussionNumber: number, tracking: false})
  }

  return {}
}

interface TableCellProps {
  item: TrafficDataItem
}
function TableCell({item}: TableCellProps) {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const siteValue = item.site

  // For popular content, use the path for linking but show the title
  const displayTitle = item.title || siteValue || 'Unknown'
  const linkPath = item.path || siteValue
  const hovercardAttributes = getHovercardAttrsForPath(linkPath, getHovercardAttributesForType)

  if (linkPath && linkPath !== 'Unknown' && !linkPath.includes('unknown-')) {
    return (
      <Link href={linkPath} target="_blank" rel="noopener noreferrer" {...hovercardAttributes}>
        <Truncate title={displayTitle} maxWidth="200px" inline>
          {displayTitle}
        </Truncate>
      </Link>
    )
  }
  return (
    <Truncate title={displayTitle} maxWidth="200px" inline>
      {displayTitle}
    </Truncate>
  )
}
